"""Naive HTTP/1.1 capture framing over fully expanded bytes."""
from ref import fp, MAX, TOKEN_CHARS

CRLF = b'\r\n'


def line(data, position):
    """-> (status, content, next) with status in ok/syntax/incomplete"""
    stop = min(len(data), position + 8194)
    found = data.find(b'\n', position, stop)
    if found < 0:
        if len(data) - position <= 8193:
            return 'incomplete', b'', position
        return 'syntax', b'', position
    if found == position or data[found - 1] != 13 or found - position - 1 > 8192:
        return 'syntax', b'', position
    return 'ok', data[position:found - 1], found + 1


def encode(rows):
    out = len(rows).to_bytes(8, 'big')
    for name, value in rows:
        out += len(name).to_bytes(8, 'big') + name
        out += len(value).to_bytes(8, 'big') + value
    return out


def field(data):
    index = data.find(b':')
    if index <= 0:
        return None
    name = data[:index]
    if any(c not in TOKEN_CHARS for c in name):
        return None
    value = data[index + 1:]
    for c in value:
        if c != 9 and not 32 <= c <= 126:
            return None
    return name, value.strip(b' \t')


def block(data, position, size, count, trailer):
    rows = []
    while True:
        status, content, nxt = line(data, position)
        if status != 'ok':
            return status, None, rows
        size += len(content) + 2
        if size > 65536:
            return 'syntax', None, rows
        if not content:
            return 'ok', nxt, rows
        item = field(content)
        if item is None:
            return 'syntax', None, rows
        if trailer and item[0].lower() in (b'host', b'content-length', b'transfer-encoding'):
            return 'syntax', None, rows
        rows.append(item)
        count += 1
        if count > 128:
            return 'syntax', None, rows
        position = nxt


def chunked(data, position):
    total = b''
    while True:
        status, content, nxt = line(data, position)
        if status != 'ok':
            return status, None, total, []
        position = nxt
        split = content.find(b';')
        digits = content if split < 0 else content[:split]
        suffix = None if split < 0 else content[split + 1:]
        if not digits or any(c not in b'0123456789abcdefABCDEF' for c in digits):
            return 'syntax', None, total, []
        if suffix is not None:
            for c in suffix:
                if c != 9 and not 32 <= c <= 126:
                    return 'syntax', None, total, []
        trimmed = digits.lstrip(b'0')
        if len(trimmed) > 16:
            return 'syntax', None, total, []
        amount = int(trimmed or b'0', 16)
        if amount > MAX:
            return 'syntax', None, total, []
        if amount == 0:
            status, end, trailers = block(data, position, 0, 0, True)
            if status != 'ok':
                return status, None, total, trailers
            return 'ok', end, total, trailers
        if len(data) - position < amount:
            return 'incomplete', None, total, []
        after = position + amount
        if len(data) - after < 2:
            return 'incomplete', None, total, []
        if data[after] != 13 or data[after + 1] != 10:
            return 'syntax', None, total, []
        total += data[position:after]
        position = after + 2


def request(data, start):
    status, content, nxt = line(data, start)
    if status != 'ok':
        return status, None, start
    pieces = content.split(b' ')
    if len(pieces) != 3:
        return 'syntax', None, start
    method, target, version = pieces
    if not method or any(c not in TOKEN_CHARS for c in method):
        return 'syntax', None, start
    if not target or any(not 33 <= c <= 126 for c in target) or version != b'HTTP/1.1':
        return 'syntax', None, start
    status, end, headers = block(data, nxt, len(content) + 2, 0, False)
    if status != 'ok':
        return status, None, start
    position = end
    lengths = [v for n, v in headers if n.lower() == b'content-length']
    encodings = [v for n, v in headers if n.lower() == b'transfer-encoding']
    framing = 'none'
    body = b''
    trailers = []
    if encodings:
        if len(encodings) > 1 or lengths or encodings[0].lower() != b'chunked':
            return 'syntax', None, start
        framing = 'chunked'
        status, position, body, trailers = chunked(data, position)
        if status != 'ok':
            return status, None, start
    elif lengths:
        total = None
        bad = False
        for value in lengths:
            for member in value.split(b','):
                digits = member.strip(b' \t')
                if not digits or any(not 48 <= c <= 57 for c in digits):
                    bad = True
                    break
                trimmed = digits.lstrip(b'0')
                if len(trimmed) > 19:
                    bad = True
                    break
                number = int(trimmed or b'0')
                if number > MAX:
                    bad = True
                    break
                if total is None:
                    total = number
                elif total != number:
                    bad = True
                    break
            if bad:
                break
        if bad:
            return 'syntax', None, start
        framing = 'length'
        if len(data) - position < total:
            return 'incomplete', None, start
        body = data[position:position + total]
        position += total
    hosts = [v for n, v in headers if n.lower() == b'host']
    return 'ok', {'start': start, 'end': position, 'method': fp(method),
                  'target': fp(target),
                  'host': fp(hosts[0].lower()) if len(hosts) == 1 else fp(b''),
                  'host_count': len(hosts), 'headers': fp(encode(headers)),
                  'body': fp(body), 'trailers': fp(encode(trailers)),
                  'framing': framing, 'owner': None, 'owners': [],
                  'flags': [], '_hosts': hosts, '_method': method,
                  '_target': target}, position


def parse(channel):
    data = b''.join(part['data'] for part in channel['parts'])
    runs = []
    position = 0
    for part in channel['parts']:
        length = len(part['data'])
        if not length:
            continue
        if runs and runs[-1][2] == part['case']:
            runs[-1][1] += length
        else:
            runs.append([position, position + length, part['case']])
        position += length
    requests = []
    error = None
    cursor = 0
    while cursor < len(data):
        status, record, nxt = parse_request(data, cursor)
        if status != 'ok':
            error = {'kind': status, 'offset': cursor}
            break
        requests.append(record)
        cursor = record['end']
    for record in requests:
        owners = []
        seen = {}
        order = []
        position = record['start']
        while position < record['end']:
            for low, high, label in runs:
                if low <= position < high:
                    stop = min(high, record['end'])
                    if label not in seen:
                        seen[label] = 0
                        order.append(label)
                    seen[label] += stop - position
                    position = stop
                    break
            else:
                break
        record['owners'] = [[label, seen[label]] for label in order]
        record['owner'] = owner_at(runs, record['start'])
    committed = []
    index = 0
    consumed = 0
    for part in channel['parts']:
        consumed += len(part['data'])
        while index < len(requests) and requests[index]['end'] <= consumed:
            index += 1
        committed.append(index)
    return {'name': channel['name'], 'bytes': fp(data), 'requests': requests,
            'committed': committed, 'error': error}


# the request-line entry point needs the shared `request` helper above
def parse_request(data, start):
    return request(data, start)


def owner_at(runs, offset):
    for low, high, label in runs:
        if low <= offset < high:
            return label
    return None
